using Mesen.Config;
using Mesen.Debugger.Utilities;
using Mesen.Interop;
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Threading;

namespace Mesen.HdStudio
{
	/// <summary>
	/// HD Studio, part 1: full level maps for SMB3, generated by the game's own level loader.
	///
	/// The disassembly gives the address of every level and the tile layout/palette tables. A small
	/// Lua driver runs in the emulator, calls the loader once per level and dumps the 6,480-byte
	/// "tile memory" the game has just built. Nothing is reimplemented: the generators (blocks,
	/// pipes, bushes, clouds...) are executed by the game itself, so the map and the tile usage are
	/// exact. HD Studio then paints those tiles with the CHR data and the level palette and writes
	/// one PNG per level plus maps.json with the exact list of background patterns each level uses.
	///
	/// The only exception is a broken generator in SMB3 (LoadLevel_LittleCloudSolidRun): its BEQ is
	/// patched to BNE in the emulator's PRG copy, which is what the disassembly says Nintendo meant
	/// to do. Without the patch those levels hang the loader (documented in prg014.asm).
	/// </summary>
	internal static class HdStudioLevelMaps
	{
		private sealed class Level
		{
			public string Name = "";
			public string Label = "";
			public string Area = "";
			public string File = "";
			public int Address;
			public int Tileset;
			public int Size;
			public int BgPalette;
			public int BgBank;
			public bool Vertical;
			public byte[] Header = Array.Empty<byte>();
			public string Png = "";
			public HashSet<int> UsedPatterns = new();
			public HashSet<(int Pattern, uint Palette)> UsedCombos = new();
		}

		private const int TileMemBytes = 6480;   //$6000-$794F: 15 screens x 432 bytes
		private const int ScreenBytes = 0x1B0;   //16 columns x 27 rows for horizontal levels
		private const int VerticalScreenBytes = 240; //16 columns x 15 rows for vertical levels

		private static readonly Regex _tilesetRegex = new(@"<tileset\s+id=""(\d+)""", RegexOptions.Compiled);
		private static readonly Regex _levelRegex = new(@"<level\s+([^>]*)>", RegexOptions.Compiled);
		private static readonly Regex _attrRegex = new("(\\w+)=\"([^\"]*)\"", RegexOptions.Compiled);
		private static readonly Regex _includeRegex = new(@"(?i)\.include\s+""([^""]+)""", RegexOptions.Compiled);

		private static readonly Dictionary<int, string> _paletteLabels = new() {
			{ 1, "PalSet_Plains" }, { 2, "PalSet_Fort" }, { 3, "PalSet_HillsUnder" }, { 4, "PalSet_HighUp" },
			{ 5, "PalSet_Plant" }, { 6, "PalSet_Water" }, { 7, "PalSet_Toad" }, { 8, "PalSet_PipeMaze" },
			{ 9, "PalSet_Desert" }, { 10, "PalSet_Airship" }, { 11, "PalSet_Giant" }, { 12, "PalSet_Ice" },
			{ 13, "PalSet_Sky" }, { 14, "PalSet_HillsUnder" }
		};

		public static bool IsAvailable(string? path) => !string.IsNullOrWhiteSpace(path) && Directory.Exists(path);

		public static int Run(string romPath, string disasmPath, string packFolder, uint[] nesPalette, Action<string> log)
		{
			string mapsFolder = Path.Combine(packFolder, HdStudioReport.StudioFolderName, "maps");
			string rawFolder = Path.Combine(mapsFolder, "raw");
			Directory.CreateDirectory(mapsFolder);
			Directory.CreateDirectory(rawFolder);
			foreach(string old in Directory.GetFiles(rawFolder, "*.bin")) {
				File.Delete(old);
			}
			foreach(string old in Directory.GetFiles(rawFolder, "*.txt")) {
				File.Delete(old);
			}
			foreach(string old in Directory.GetFiles(mapsFolder, "*.png")) {
				File.Delete(old);
			}

			log("Level maps: reading the disassembly and locating every level in the ROM...");
			List<Level> levels = LoadLevels(disasmPath, romPath, log);
			if(levels.Count == 0) {
				log("Level maps: no levels found. Is this the right disassembly?");
				return -1;
			}

			byte[] rom = File.ReadAllBytes(romPath);
			int headerSize = rom.Length >= 16 && rom[0] == 'N' && rom[1] == 'E' && rom[2] == 'S' && rom[3] == 0x1A
				? 16 + ((rom[6] & 0x04) != 0 ? 512 : 0) : 0;
			int prgSize = rom.Length >= 16 ? rom[4] * 0x4000 : 0;
			ReadOnlySpan<byte> prg = rom.AsSpan(headerSize, Math.Min(prgSize, rom.Length - headerSize));

			//The driver calls fixed SMB3 routines ($897B -> LevelLoad_ByTileset, return at $89A0,
			//hooked NMI at $F486). Refuse other games instead of producing nonsense.
			ReadOnlySpan<byte> loaderSignature = new byte[] { 0xA9, 0x00, 0x8D, 0xF2, 0x7C, 0xAD, 0x0A, 0x07, 0xC9, 0x10, 0xF0 };
			if(prg.IndexOf(loaderSignature) < 0) {
				log("Level maps: this pass currently supports the SMB3 level loader only (the level data format is game-specific).");
				return -1;
			}

			//The broken generator: LDX #$01 / BEQ +4 / .byte TILE1_JCLOUD, TILE1_JCLOUDSOLID
			int patchOffset = -1;
			ReadOnlySpan<byte> brokenGenerator = new byte[] { 0xA2, 0x01, 0xF0, 0x04, 0x2C, 0x2D };
			int found = prg.IndexOf(brokenGenerator);
			if(found >= 0) {
				patchOffset = found + 2; //the BEQ opcode
			}

			string luaPath = Path.Combine(mapsFolder, "driver.lua");
			File.WriteAllText(luaPath, BuildLua(levels, rawFolder, patchOffset), new UTF8Encoding(false));
			log($"Level maps: {levels.Count} levels found; booting the game to run its own generator for each one...");

			int dumped = RunDriver(romPath, luaPath, rawFolder, levels.Count, log);
			int rendered;
			try {
				rendered = RenderMaps(levels, rawFolder, mapsFolder, rom, disasmPath, nesPalette, log);
				WriteManifest(levels, mapsFolder, romPath, log);
				WriteSpriteSweep(mapsFolder, disasmPath, log);
			} catch(Exception ex) {
				log("Level maps: " + ex.Message);
				return -3;
			}

			log($"Level maps: {rendered} maps written to {mapsFolder}");
			return rendered > 0 ? 0 : -2;
		}

		#region Disassembly parsing

		private static List<Level> LoadLevels(string disasmPath, string romPath, Action<string> log)
		{
			string root = Directory.Exists(disasmPath) ? disasmPath : Path.GetDirectoryName(disasmPath) ?? disasmPath;
			string[] asmFiles = Directory.GetFiles(root, "*.asm", SearchOption.AllDirectories);
			if(asmFiles.Length == 0) {
				log("Level maps: the disassembly folder has no .asm files.");
				return new List<Level>();
			}

			string? gameXml = asmFiles.FirstOrDefault(f => Path.GetFileName(f).Equals("game.xml", StringComparison.OrdinalIgnoreCase));
			gameXml ??= Path.Combine(root, "game.xml");
			if(!File.Exists(gameXml)) {
				log("Level maps: game.xml not found in the disassembly folder (it names the levels).");
				return new List<Level>();
			}

			//label -> file of the .include it labels (the label sits at the start of the level data)
			Dictionary<string, string> labelFile = BuildLabelFileMap(root, asmFiles);

			byte[] rom = File.ReadAllBytes(romPath);
			int headerSize = rom.Length >= 16 && rom[0] == 'N' && rom[1] == 'E' && rom[2] == 'S' && rom[3] == 0x1A
				? 16 + ((rom[6] & 0x04) != 0 ? 512 : 0) : 0;
			int prgSize = rom.Length >= 16 ? rom[4] * 0x4000 : 0;
			byte[] prg = rom.AsSpan(headerSize, Math.Min(prgSize, rom.Length - headerSize)).ToArray();
			if(prg.Length == 0) {
				log("Level maps: the ROM has no PRG data.");
				return new List<Level>();
			}

			//A000 bank per tileset (LevelLoad uses PAGE_A000_ByTileset to choose the level data bank)
			byte[] pageA000 = ParseLabel(asmFiles, "PAGE_A000_ByTileset", 32) ?? Array.Empty<byte>();

			List<Level> result = new();
			HashSet<string> seen = new();
			int tileset = -1;
			int skippedBonus = 0;
			foreach(string line in File.ReadLines(gameXml)) {
				Match m = _tilesetRegex.Match(line);
				if(m.Success && int.TryParse(m.Groups[1].Value, out int ts)) {
					tileset = ts;
				}

				m = _levelRegex.Match(line);
				if(!m.Success || tileset < 1 || tileset > 14) {
					continue;
				}

				Dictionary<string, string> attrs = _attrRegex.Matches(m.Groups[1].Value)
					.Cast<Match>().ToDictionary(a => a.Groups[1].Value, a => a.Groups[2].Value);
				if(!attrs.TryGetValue("layoutlabel", out string? label) || string.IsNullOrEmpty(label) || !labelFile.TryGetValue(label, out string? file)) {
					continue;
				}
				if(label.StartsWith("PJ", StringComparison.Ordinal)) {
					//Pipe junction fragments: alternate layouts inside a parent level, not standalone
					continue;
				}
				string name = attrs.GetValueOrDefault("name") ?? Path.GetFileNameWithoutExtension(file);
				if(name.Contains("Big [?] Block") || name.Contains("(maybe)")) {
					//Bonus sub-areas that are entered through a pipe: they inherit the parent's
					//tileset and are not standalone levels (they also hang the loader when forced).
					skippedBonus++;
					continue;
				}

				byte[]? layout = ParseLayout(file, out int headerValues);
				if(layout == null || layout.Length < 4 || headerValues < 5) {
					continue;
				}

				if(!LocateLevel(prg, layout, tileset, pageA000, out int pos, out byte[] levelHeader)) {
					continue;
				}

				if(!seen.Add(label + "/" + tileset)) {
					continue;
				}

				//The loader takes a pointer to the 9-byte level header, which sits right before the layout data
				int headerPosition = pos - 9;
				int address = 0xA000 + (headerPosition % 0x2000);
				result.Add(new Level() {
					Name = name,
					Label = label,
					Area = attrs.GetValueOrDefault("desc") ?? "",
					File = Path.GetRelativePath(root, file).Replace('\\', '/'),
					Address = address,
					Tileset = tileset,
					Size = levelHeader[4] & 0x0F,
					BgPalette = levelHeader[5] & 0x07,
					BgBank = levelHeader[7] & 0x1F,
					Vertical = (levelHeader[6] & 0x10) != 0,
					Header = levelHeader
				});
			}

			log($"Level maps: {result.Count} standalone levels parsed ({skippedBonus} bonus sub-areas skipped), " +
				$"{result.Select(l => l.Tileset).Distinct().Count()} tilesets.");
			return result;
		}

		private static Dictionary<string, string> BuildLabelFileMap(string root, string[] asmFiles)
		{
			Dictionary<string, string> map = new(StringComparer.OrdinalIgnoreCase);
			foreach(string areaFile in asmFiles.Where(f => Path.GetDirectoryName(f)!.Equals(Path.Combine(root, "PRG", "levels"), StringComparison.OrdinalIgnoreCase))) {
				string current = "";
				foreach(string line in File.ReadLines(areaFile)) {
					string text = line.Split(';')[0].Trim();
					Match label = Regex.Match(text, @"^([A-Za-z_]\w*)\s*:");
					if(label.Success) {
						current = label.Groups[1].Value;
					}
					Match inc = _includeRegex.Match(text);
					if(inc.Success && current.Length > 0) {
						string? target = ResolveInclude(root, inc.Groups[1].Value);
						if(target != null) {
							map[current] = target;
						}
					}
				}
			}
			return map;
		}

		private static string? ResolveInclude(string root, string name)
		{
			foreach(string baseFolder in new[] { root, Path.Combine(root, "PRG") }) {
				string path = Path.GetFullPath(Path.Combine(baseFolder, name));
				if(File.Exists(path)) {
					return path;
				}
				//NESASM includes omit the extension: "1-K" is "1-K.asm" even though
				//Path.HasExtension thinks ".K" is an extension.
				if(File.Exists(path + ".asm")) {
					return path + ".asm";
				}
			}
			return null;
		}

		/// <summary>Byte data of a level file: the first 5 .byte values are the header, the rest is the layout</summary>
		private static byte[]? ParseLayout(string file, out int headerValues)
		{
			headerValues = 0;
			List<byte> data = new();
			bool sawWord = false;
			foreach(string rawLine in File.ReadLines(file)) {
				string line = rawLine.Split(';')[0].Trim();
				if(line.Length == 0) {
					continue;
				}
				if(line.StartsWith(".word", StringComparison.OrdinalIgnoreCase) || line.StartsWith(".dw", StringComparison.OrdinalIgnoreCase)) {
					sawWord = true;
					continue;
				}
				Match m = Regex.Match(line, @"(?i)^\.(byte|db)\s+(.*)$");
				if(!m.Success) {
					continue;
				}
				foreach(string value in m.Groups[2].Value.Split(',')) {
					string token = value.Trim();
					if(token.Length == 0) {
						continue;
					}
					if(headerValues < 5) {
						headerValues++;
						continue;
					}
					if(TryParseByte(token, out byte b)) {
						data.Add(b);
					}
				}
			}
			return sawWord && data.Count > 0 ? data.ToArray() : null;
		}

		private static bool TryParseHex(string token, out int value)
		{
			return int.TryParse(token.Trim(), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value);
		}

		private static bool TryParseHex(string token, out uint value)
		{
			return uint.TryParse(token.Trim(), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value);
		}

		private static bool TryParseByte(string token, out byte value)
		{
			value = 0;
			token = token.Trim();
			if(token.StartsWith("$")) {
				return byte.TryParse(token.Substring(1), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value);
			}
			if(token.StartsWith("%")) {
				try {
					value = Convert.ToByte(token.Substring(1), 2);
					return true;
				} catch {
					return false;
				}
			}
			if(token.All(char.IsDigit)) {
				return byte.TryParse(token, out value);
			}
			return false;
		}

		private static bool LocateLevel(byte[] prg, byte[] layout, int tileset, byte[] pageA000, out int position, out byte[] header)
		{
			position = -1;
			header = Array.Empty<byte>();
			int prefixLength = Math.Min(48, layout.Length);
			ReadOnlySpan<byte> prefix = layout.AsSpan(0, prefixLength);
			int expectedBank = tileset < pageA000.Length ? pageA000[tileset] : -1;

			int search = 0;
			int fallback = -1;
			while(search < prg.Length) {
				int index = prg.AsSpan(search).IndexOf(prefix);
				if(index < 0) {
					break;
				}
				int pos = search + index;
				search = pos + 1;
				if(pos < 9) {
					continue;
				}

				byte[] candidate = prg.AsSpan(pos - 9, 9).ToArray();
				int bank = pos / 0x2000;
				int altTileset = candidate[6] & 0x0F;
				int bgBank = candidate[7] & 0x1F;
				if((candidate[4] & 0x0F) > 15 || altTileset > 18 || bgBank > 31) {
					continue;
				}

				if(expectedBank < 0 || bank == expectedBank) {
					position = pos;
					header = candidate;
					return true;
				}
				if(fallback < 0) {
					fallback = pos;
					header = candidate;
				}
			}

			if(fallback >= 0) {
				position = fallback;
				return true;
			}
			return false;
		}

		private static byte[]? ParseLabel(string[] asmFiles, string label, int maxBytes)
		{
			foreach(string file in asmFiles) {
				byte[]? data = HdStudioDisasm.ParseBytes(file, label, maxBytes);
				if(data != null && data.Length > 0) {
					return data;
				}
			}
			return null;
		}

		#endregion

		#region Emulator driver

		private static string BuildLua(List<Level> levels, string rawFolder, int patchOffset)
		{
			string Esc(string s) => "'" + s.Replace("\\", "\\\\").Replace("'", "\\'") + "'";
			string folder = rawFolder.Replace("\\", "/");

			StringBuilder sb = new();
			sb.AppendLine("-- HD Studio level maps: runs the game's own level loader once per level");
			sb.AppendLine("local OUT = " + Esc(folder));
			sb.AppendLine("local PATCH = " + patchOffset);
			sb.AppendLine("local levels = {");
			foreach(Level l in levels) {
				sb.AppendLine($"  {{addr=0x{l.Address:X4}, ts={l.Tileset}, name={Esc(l.Name)}}},");
			}
			sb.AppendLine("}");
			sb.AppendLine(@"
local logFile = io.open(OUT .. '/dump.log', 'w')
local progressFile = io.open(OUT .. '/progress.txt', 'w')
local frame = 0
local armed = false
local index = 0

local function log(s)
  emu.log(s)
  if logFile then logFile:write(s .. '\n'); logFile:flush() end
end

local function progress()
  if progressFile then
    progressFile:seek('set')
    progressFile:write(tostring(index) .. '\n')
    progressFile:flush()
  end
end

local function dumpTileMem(path)
  local b = io.open(path, 'wb')
  for i = 0, 6479, 256 do
    local chunk = {}
    for j = i, math.min(i + 255, 6479) do
      chunk[#chunk + 1] = emu.read(0x6000 + j, emu.memType.nesMemory)
    end
    b:write(string.char(table.unpack(chunk)))
  end
  b:close()
end

local function armLevel(idx)
  local L = levels[idx + 1]
  if PATCH and PATCH >= 0 then
    emu.write(PATCH, 0xD0, emu.memType.nesPrgRom) -- BEQ -> BNE (broken solid-cloud generator)
  end
  emu.write(0x2000, 0x00, emu.memType.nesMemory)   -- PPU NMI off: the loader must not be interrupted
  emu.write(0x00FF, 0x00, emu.memType.nesMemory)
  emu.write(0xE000, 0x00, emu.memType.nesMemory)   -- MMC3 IRQ off
  emu.write(0x03DE, 0x00, emu.memType.nesMemory)   -- Level_JctCtl
  emu.write(0x03EF, 0x00, emu.memType.nesMemory)   -- Level_7Vertical (the loader sets it again)
  emu.write(0x070A, L.ts, emu.memType.nesMemory)   -- Level_Tileset
  emu.write(0x0061, L.addr & 0xFF, emu.memType.nesMemory)
  emu.write(0x0062, (L.addr >> 8) & 0xFF, emu.memType.nesMemory)
  for i = 0, 127 do
    emu.write(0x7E02 + i, 0x00, emu.memType.nesMemory) -- collected coins / 1-ups
  end
  emu.setCpuState({pc = 0x897B})
end

-- $897B is the block that switches the PRG banks and calls LevelLoad_ByTileset;
-- $89A0 is the instruction right after that call.
emu.addMemoryCallback(function(addr, value)
  local L = levels[index + 1]
  dumpTileMem(string.format('%s/%03d.bin', OUT, index))
  log(string.format('%d %s', index, L.name))
  index = index + 1
  progress()
  if index >= #levels then
    log('done: ' .. index .. ' levels')
    local done = io.open(OUT .. '/done.txt', 'w')
    done:write('done ', index, '\n')
    done:close()
    emu.stop()
    return
  end
  armLevel(index)
end, emu.callbackType.exec, 0x89A0, 0x89A0)

emu.addMemoryCallback(function(addr, value)
  if not armed then return end
  armed = false
  log('start')
  armLevel(0)
end, emu.callbackType.exec, 0xF486, 0xF486)

emu.addEventCallback(function()
  frame = frame + 1
  if frame == 180 then armed = true end
end, emu.eventType.startFrame)
");
			return sb.ToString();
		}

		private static int RunDriver(string romPath, string luaPath, string rawFolder, int levelCount, Action<string> log)
		{
			bool oldIo = ConfigManager.Config.Debug.ScriptWindow.AllowIoOsAccess;
			uint oldTimeout = ConfigManager.Config.Debug.ScriptWindow.ScriptTimeout;
			try {
				ConfigManager.Config.Debug.ScriptWindow.AllowIoOsAccess = true;
				ConfigManager.Config.Debug.ScriptWindow.ScriptTimeout = 10;

				EmuApi.InitDll();
				ConfigManager.Config.ApplyConfig();
				EmuApi.InitializeEmu(ConfigManager.HomeFolder, IntPtr.Zero, IntPtr.Zero, true, true, true, true);
				EmuApi.Pause();
				ConfigApi.SetEmulationFlag(EmulationFlags.ConsoleMode, true);

				if(!EmuApi.LoadRom(romPath, string.Empty)) {
					log("Level maps: the ROM could not be loaded.");
					return 0;
				}
				if(EmuApi.GetRomInfo().ConsoleType != ConsoleType.Nes) {
					log("Level maps: only NES games are supported.");
					return 0;
				}

				DebugWorkspaceManager.Load();
				string script = File.ReadAllText(luaPath);
				DebugApi.LoadScript(Path.GetFileName(luaPath), Path.GetDirectoryName(luaPath) + Path.DirectorySeparatorChar, script);

				ConfigApi.SetEmulationFlag(EmulationFlags.MaximumSpeed, true);
				EmuApi.Resume();

				string doneFile = Path.Combine(rawFolder, "done.txt");
				string progressFile = Path.Combine(rawFolder, "progress.txt");
				Stopwatch sw = Stopwatch.StartNew();
				int lastProgress = -1;
				while(sw.Elapsed.TotalSeconds < 180) {
					Thread.Sleep(100);
					if(File.Exists(doneFile)) {
						break;
					}
					if(!EmuApi.IsRunning()) {
						break;
					}
					int progress = ReadInt(progressFile);
					if(progress != lastProgress) {
						lastProgress = progress;
						log($"  {progress}/{levelCount} level maps...");
					}
				}

				int dumped = ReadInt(progressFile);
				if(!File.Exists(doneFile)) {
					log($"Level maps: the loader stopped after {dumped} levels (timeout or an unsupported level).");
				}
				EmuApi.Pause();
				EmuApi.Stop();
				EmuApi.Release();
				return dumped;
			} catch(Exception ex) {
				log("Level maps: " + ex.Message);
				return 0;
			} finally {
				//Only the in-memory configuration is restored: the emulator has been released, so
				//pushing the debug config to the core at this point would crash. The next
				//ApplyConfig (capture/report) sees the restored values.
				ConfigManager.Config.Debug.ScriptWindow.AllowIoOsAccess = oldIo;
				ConfigManager.Config.Debug.ScriptWindow.ScriptTimeout = oldTimeout;
			}
		}

		private static int ReadInt(string path)
		{
			try {
				if(File.Exists(path) && int.TryParse(File.ReadAllText(path).Trim(), out int value)) {
					return value;
				}
			} catch {
			}
			return 0;
		}

		#endregion

		#region Rendering

		private static int RenderMaps(List<Level> levels, string rawFolder, string mapsFolder, byte[] rom, string disasmPath, uint[] nesPalette, Action<string> log)
		{
			string[] asmFiles = Directory.GetFiles(disasmPath, "*.asm", SearchOption.AllDirectories);
			Dictionary<int, byte[]> layouts = ParseLayoutTables(asmFiles);
			if(layouts.Count == 0) {
				log("Level maps: no tile layout tables found in the disassembly.");
				return 0;
			}

			byte[] pages1 = ParseLabel(asmFiles, "Level_BG_Pages1", 32) ?? Array.Empty<byte>();
			byte[] pages2 = ParseLabel(asmFiles, "Level_BG_Pages2", 32) ?? Array.Empty<byte>();
			byte[] verticalLow = ParseLabel(asmFiles, "Tile_Mem_AddrVL", 16) ?? Array.Empty<byte>();
			byte[] verticalHigh = ParseLabel(asmFiles, "Tile_Mem_AddrVH", 16) ?? Array.Empty<byte>();
			Dictionary<int, byte[]> palettes = new();
			foreach(KeyValuePair<int, string> kv in _paletteLabels) {
				byte[]? pal = ParseLabel(asmFiles, kv.Value, 128);
				if(pal != null && pal.Length >= 64) {
					palettes[kv.Key] = pal;
				}
			}
			byte[] chr = GetChr(rom);

			int written = 0;
			foreach(Level level in levels) {
				string raw = Path.Combine(rawFolder, $"{written:000}.bin");
				if(!File.Exists(raw)) {
					break;
				}
				if(!layouts.TryGetValue(level.Tileset, out byte[]? layout) || !palettes.TryGetValue(level.Tileset, out byte[]? palette)) {
					written++;
					continue;
				}

				byte[] data = File.ReadAllBytes(raw);
				string pngName = $"{written:000}_{SafeName(level.Name)}_{level.Label}.png";
				string pngPath = Path.Combine(mapsFolder, pngName);
				RenderLevel(level, data, layout, palette, pages1, pages2, verticalLow, verticalHigh, chr, nesPalette, pngPath, level.UsedPatterns);
				level.Png = pngName;
				written++;
			}

			return written;
		}

		private static Dictionary<int, byte[]> ParseLayoutTables(string[] asmFiles)
		{
			Dictionary<int, byte[]> result = new();
			Dictionary<int, string> names = new() {
				{ 1, "Tile_Layout_TS1" }, { 2, "Tile_Layout_TS2" }, { 3, "Tile_Layout_TS3" },
				{ 4, "Tile_Layout_TS4_TS12" }, { 5, "Tile_Layout_TS5_TS11_TS13" }, { 6, "Tile_Layout_TS6_TS7_TS8" },
				{ 7, "Tile_Layout_TS6_TS7_TS8" }, { 8, "Tile_Layout_TS6_TS7_TS8" }, { 9, "Tile_Layout_TS9" },
				{ 10, "Tile_Layout_TS10" }, { 11, "Tile_Layout_TS5_TS11_TS13" }, { 12, "Tile_Layout_TS4_TS12" },
				{ 13, "Tile_Layout_TS5_TS11_TS13" }, { 14, "Tile_Layout_TS14" }
			};
			foreach(KeyValuePair<int, string> kv in names) {
				byte[]? data = ParseLabel(asmFiles, kv.Value, 1024);
				if(data != null && data.Length == 1024) {
					result[kv.Key] = data;
				}
			}
			return result;
		}

		private static byte[] GetChr(byte[] rom)
		{
			if(rom.Length < 16 || rom[0] != 'N' || rom[1] != 'E' || rom[2] != 'S' || rom[3] != 0x1A) {
				return Array.Empty<byte>();
			}
			int offset = 16 + ((rom[6] & 0x04) != 0 ? 512 : 0);
			int prgSize = rom[4] * 0x4000;
			int chrSize = rom[5] * 0x2000;
			int start = offset + prgSize;
			int length = Math.Max(0, Math.Min(chrSize, rom.Length - start));
			byte[] chr = new byte[length];
			Array.Copy(rom, start, chr, 0, length);
			return chr;
		}

		private static void RenderLevel(Level level, byte[] data, byte[] layout, byte[] palette, byte[] pages1, byte[] pages2,
			byte[] verticalLow, byte[] verticalHigh, byte[] chr, uint[] nesPalette, string path, HashSet<int> used)
		{
			int screens = Math.Min(level.Size + 1, 15);
			int width = level.Vertical ? 16 : screens * 16;
			int height = level.Vertical ? screens * 15 : 27;
			byte[,] grid = new byte[height, width];

			if(level.Vertical) {
				for(int s = 0; s < screens && s < 16; s++) {
					int baseAddr = (verticalHigh.Length > s ? verticalHigh[s] : 0x60 + s) * 256
						+ (verticalLow.Length > s ? verticalLow[s] : 0) - 0x6000;
					for(int r = 0; r < 15; r++) {
						for(int c = 0; c < 16; c++) {
							int index = baseAddr + r * 16 + c;
							grid[s * 15 + r, c] = index >= 0 && index < data.Length ? data[index] : (byte)0x80;
						}
					}
				}
			} else {
				for(int s = 0; s < screens; s++) {
					int baseAddr = s * ScreenBytes;
					for(int r = 0; r < 27; r++) {
						for(int c = 0; c < 16; c++) {
							int index = baseAddr + r * 16 + c;
							grid[r, s * 16 + c] = index < data.Length ? data[index] : (byte)0x80;
						}
					}
				}
			}

			int page1 = level.BgBank < pages1.Length ? pages1[level.BgBank] : 0;
			int page2 = level.BgBank < pages2.Length ? pages2[level.BgBank] : 0;
			uint[] pixels = new uint[width * 16 * height * 16];

			for(int y = 0; y < height; y++) {
				for(int x = 0; x < width; x++) {
					int tile = grid[y, x];
					int sub = (tile >> 6) & 3;
					int palOffset = level.BgPalette * 16 + sub * 4;
					uint[] colors = new uint[4];
					bool hasPalette = palette.Length >= palOffset + 4;
					uint packedPalette = 0;
					if(hasPalette) {
						for(int i = 0; i < 4; i++) {
							colors[i] = nesPalette[palette[palOffset + i] & 0x3F] | 0xFF000000;
						}
						//Color 0 of every sub-palette is the same backdrop on the NES
						colors[0] = nesPalette[palette[level.BgPalette * 16] & 0x3F] | 0xFF000000;
						packedPalette = ((uint)palette[level.BgPalette * 16] << 24)
							| ((uint)palette[palOffset + 1] << 16)
							| ((uint)palette[palOffset + 2] << 8)
							| palette[palOffset + 3];
					}

					for(int q = 0; q < 4; q++) {
						int pattern = layout[q * 256 + tile];
						int absolute = pattern < 128 ? page1 * 64 + pattern : page2 * 64 + (pattern - 128);
						if(absolute < 0 || (absolute + 1) * 16 > chr.Length) {
							continue;
						}
						used.Add(absolute);
						if(hasPalette) {
							level.UsedCombos.Add((absolute, packedPalette));
						}
						//SMB3 stores the four 8x8 chunks as upper-left, lower-left, upper-right,
						//lower-right (not row-major). The old q&1/q>>1 order swapped the two
						//diagonal quadrants and made complex 16x16 tiles look shifted.
						int ox = x * 16 + (q >> 1) * 8;
						int oy = y * 16 + (q & 1) * 8;
						for(int py = 0; py < 8; py++) {
							byte lo = chr[absolute * 16 + py];
							byte hi = chr[absolute * 16 + 8 + py];
							for(int px = 0; px < 8; px++) {
								int ci = ((lo >> (7 - px)) & 1) | (((hi >> (7 - px)) & 1) << 1);
								pixels[(oy + py) * width * 16 + ox + px] = colors[ci];
							}
						}
					}
				}
			}

			HdStudioPng.Write(path, pixels, width * 16, height * 16);
		}

		#endregion

		#region Manifest

		private static void WriteManifest(List<Level> levels, string mapsFolder, string romPath, Action<string> log)
		{
			byte[] rom = File.ReadAllBytes(romPath);
			byte[] chr = GetChr(rom);
			HashSet<int> blank = new();
			for(int i = 0; i + 16 <= chr.Length; i += 16) {
				bool isBlank = true;
				for(int j = 0; j < 16; j++) {
					if(chr[i + j] != 0) {
						isBlank = false;
						break;
					}
				}
				if(isBlank) {
					blank.Add(i / 16);
				}
			}

			HashSet<int> seen = new();
			string tilesTxt = Path.Combine(Path.GetDirectoryName(mapsFolder)!, "tiles.txt");
			if(File.Exists(tilesTxt)) {
				foreach(string line in File.ReadLines(tilesTxt)) {
					if(line.Length == 0 || line[0] == '#') {
						continue;
					}
					string[] parts = line.Split('\t');
					if(parts.Length >= 2 && int.TryParse(parts[0], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int tile)) {
						seen.Add(tile);
					}
				}
			}

			HashSet<int> used = new();
			HashSet<(int Pattern, uint Palette)> usedCombos = new();
			int levelCount = 0;
			foreach(Level level in levels) {
				if(string.IsNullOrEmpty(level.Png)) {
					continue;
				}
				used.UnionWith(level.UsedPatterns);
				usedCombos.UnionWith(level.UsedCombos);
				levelCount++;
			}

			int nonBlank = Math.Max(0, chr.Length / 16 - blank.Count);
			HashSet<int> usedNonBlank = used.Where(t => !blank.Contains(t)).ToHashSet();
			int seenReferenced = usedNonBlank.Count(t => seen.Contains(t));
			double coverage = usedNonBlank.Count > 0 ? 100.0 * seenReferenced / usedNonBlank.Count : 0;

			//Write the manifest by hand: the UI is published trimmed and reflection-based
			//System.Text.Json serialization of anonymous types is not trimming-safe.
			using(FileStream stream = File.Create(Path.Combine(mapsFolder, "maps.json")))
			using(Utf8JsonWriter writer = new(stream, new JsonWriterOptions() { Indented = true })) {
				writer.WriteStartObject();
				writer.WriteString("rom", Path.GetFileName(romPath));
				writer.WriteStartArray("levels");
				foreach(Level level in levels) {
					if(string.IsNullOrEmpty(level.Png)) {
						continue;
					}
					writer.WriteStartObject();
					writer.WriteString("name", level.Name);
					writer.WriteString("label", level.Label);
					writer.WriteNumber("tileset", level.Tileset);
					writer.WriteNumber("bgpalette", level.BgPalette);
					writer.WriteNumber("bgbank", level.BgBank);
					writer.WriteNumber("size", level.Size);
					writer.WriteBoolean("vertical", level.Vertical);
					writer.WriteString("file", level.File);
					writer.WriteString("png", level.Png);
					writer.WriteNumber("patterns", level.UsedPatterns.Count);
					writer.WriteNumber("combos", level.UsedCombos.Count);
					writer.WriteStartArray("tiles");
					foreach(int pattern in level.UsedPatterns.OrderBy(p => p)) {
						writer.WriteNumberValue(pattern);
					}
					writer.WriteEndArray();
					writer.WriteEndObject();
				}
				writer.WriteEndArray();
				writer.WriteStartObject("summary");
				writer.WriteNumber("levels", levelCount);
				writer.WriteNumber("patterns", used.Count);
				writer.WriteNumber("nonBlankPatterns", usedNonBlank.Count);
				writer.WriteNumber("exactCombos", usedCombos.Count);
				writer.WriteNumber("seenPatterns", seenReferenced);
				writer.WriteNumber("coveragePercent", Math.Round(coverage, 1));
				writer.WriteNumber("chrPatterns", chr.Length / 16);
				writer.WriteNumber("chrNonBlank", nonBlank);
				writer.WriteEndObject();
				writer.WriteEndObject();
			}

			StringBuilder txt = new();
			txt.AppendLine("# HD Studio level maps");
			txt.AppendLine($"# levels: {levelCount}, background patterns: {usedNonBlank.Count} non-blank, {seenReferenced} present in the pack ({coverage:0.0}%), exact pattern+palette combinations: {usedCombos.Count}");
			txt.AppendLine("# level\ttileset\tbgpal\tbgbank\tsize\tvertical\tpng\tpatterns");
			foreach(Level level in levels) {
				if(string.IsNullOrEmpty(level.Png)) {
					continue;
				}
				txt.AppendLine($"{level.Name}\t{level.Tileset}\t{level.BgPalette}\t{level.BgBank}\t{level.Size}\t{level.Vertical}\t{level.Png}\t{level.UsedPatterns.Count}");
			}
			File.WriteAllText(Path.Combine(mapsFolder, "maps.txt"), txt.ToString());

			//Exact per-level tile usage: one line per level, absolute CHR pattern indexes (8x8 tiles)
			StringBuilder usage = new();
			usage.AppendLine("# HD Studio exact per-level background tile usage (absolute CHR pattern indexes)");
			foreach(Level level in levels) {
				if(string.IsNullOrEmpty(level.Png)) {
					continue;
				}
				usage.Append(level.Name).Append(" [").Append(level.Label).Append("]: ");
				usage.AppendLine(string.Join(",", level.UsedPatterns.OrderBy(p => p).Select(p => p.ToString("X4"))));
			}
			File.WriteAllText(Path.Combine(mapsFolder, "maps_tiles.txt"), usage.ToString());

			//Exact background combinations (CHR pattern + 4-color palette) used by the maps.
			//HdPackBuilder reads this file and adds the missing entries to the pack, so every placed
			//background tile gets the palette the game really uses (not a guessed one).
			StringBuilder exact = new();
			exact.AppendLine("# HD Studio exact background combinations: <pattern> <palette>");
			exact.AppendLine("# palette is the 4 NES color indexes packed as [color0][color1][color2][color3]");
			foreach((int pattern, uint palette) in usedCombos.OrderBy(c => c.Pattern).ThenBy(c => c.Palette)) {
				exact.Append(pattern.ToString("X4")).Append(' ').AppendLine(palette.ToString("X8"));
			}
			File.WriteAllText(Path.Combine(mapsFolder, "tiles_exact.txt"), exact.ToString());

			log($"Level maps: {usedNonBlank.Count:N0} non-blank background patterns referenced by the levels " +
				$"({100.0 * usedNonBlank.Count / Math.Max(1, nonBlank):0.0}% of the cartridge); " +
				$"{seenReferenced:N0} of them are in the pack ({coverage:0.0}%).");
			log($"Level maps: {usedCombos.Count:N0} exact (pattern + palette) background combinations written to tiles_exact.txt.");
		}

		/// <summary>
		/// Sprite palette sweep: every sprite pattern ever seen in tiles.txt/objects.txt, combined
		/// with all 42 real sprite palettes of the game's 14 tilesets. The pack can then match a
		/// sprite with any of its possible palettes, even if that exact pair was never captured.
		/// </summary>
		private static void WriteSpriteSweep(string mapsFolder, string disasmPath, Action<string> log)
		{
			string studio = Path.GetDirectoryName(mapsFolder)!;
			HashSet<int> patterns = new();

			string tilesTxt = Path.Combine(studio, "tiles.txt");
			if(File.Exists(tilesTxt)) {
				foreach(string line in File.ReadLines(tilesTxt)) {
					if(line.Length == 0 || line[0] == '#') {
						continue;
					}
					string[] parts = line.Split('\t');
					if(parts.Length >= 2 && TryParseHex(parts[0], out int tile) && TryParseHex(parts[1], out uint palette)) {
						if((palette >> 24) == 0xFF) {
							patterns.Add(tile);
						}
					}
				}
			}

			string objectsTxt = Path.Combine(studio, "objects.txt");
			if(File.Exists(objectsTxt)) {
				Regex spriteRegex = new(@"-?\d+,-?\d+,([0-9A-Fa-f]+),([0-9A-Fa-f]+),\d+;");
				foreach(string line in File.ReadLines(objectsTxt)) {
					foreach(Match m in spriteRegex.Matches(line)) {
						if(TryParseHex(m.Groups[1].Value, out int tile) && TryParseHex(m.Groups[2].Value, out uint palette)) {
							if((palette >> 24) == 0xFF) {
								patterns.Add(tile);
							}
						}
					}
				}
			}

			if(patterns.Count == 0) {
				return;
			}

			string[] asmFiles = Directory.GetFiles(disasmPath, "*.asm", SearchOption.AllDirectories);
			HashSet<uint> palettes = new();
			foreach(string label in _paletteLabels.Values.Distinct()) {
				byte[]? data = ParseLabel(asmFiles, label, 192);
				if(data == null || data.Length < 192) {
					continue;
				}
				//8 BG palettes (128 bytes), then 4 OBJPAL sets x 4 sprite palettes of 4 colors
				for(int set = 0; set < 4; set++) {
					for(int group = 0; group < 4; group++) {
						int offset = 128 + set * 16 + group * 4;
						uint palette = 0xFF000000
							| ((uint)data[offset + 1] << 16)
							| ((uint)data[offset + 2] << 8)
							| data[offset + 3];
						palettes.Add(palette);
					}
				}
			}
			if(palettes.Count == 0) {
				return;
			}

			StringBuilder sb = new();
			sb.AppendLine("# HD Studio sprite combinations: seen sprite patterns x every real sprite palette");
			sb.AppendLine("# pattern palette (sprite form, FF + 3 NES color indexes)");
			foreach(int pattern in patterns.OrderBy(p => p)) {
				foreach(uint palette in palettes.OrderBy(p => p)) {
					sb.Append(pattern.ToString("X4")).Append(' ').AppendLine(palette.ToString("X8"));
				}
			}
			File.WriteAllText(Path.Combine(mapsFolder, "sprites_exact.txt"), sb.ToString());
			log($"Level maps: sprite sweep {patterns.Count:N0} patterns x {palettes.Count} real palettes = {patterns.Count * palettes.Count:N0} exact sprite combinations.");
		}

		private static string SafeName(string name)
		{
			StringBuilder sb = new();
			foreach(char c in name) {
				sb.Append(char.IsLetterOrDigit(c) || c == '-' || c == '_' ? c : '_');
			}
			return sb.Length == 0 ? "level" : sb.ToString();
		}

		#endregion
	}
}
